BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SELECT plan(12);
INSERT INTO auth.users(id) VALUES ('00000000-0000-0000-0000-000000000011'), ('00000000-0000-0000-0000-000000000012'), ('00000000-0000-0000-0000-000000000013');
INSERT INTO public.user_roles VALUES ('00000000-0000-0000-0000-000000000013','vpn_admin');
INSERT INTO public.provider_connections(id,user_id,provider_user_id,login,consent_version,consented_at) VALUES ('10000000-0000-0000-0000-000000000011','00000000-0000-0000-0000-000000000011','11','owner','monitoring-v1',now());
INSERT INTO public.channels(id,connection_id,owner_id) VALUES ('20000000-0000-0000-0000-000000000011','10000000-0000-0000-0000-000000000011','00000000-0000-0000-0000-000000000011');
SELECT is((SELECT monitoring_enabled FROM public.channels WHERE id='20000000-0000-0000-0000-000000000011'),false,'monitoring defaults off');
SELECT throws_ok($$UPDATE public.channels SET monitoring_enabled=true WHERE id='20000000-0000-0000-0000-000000000011'$$,'23514',NULL,'monitoring requires v2 consent');
UPDATE public.channels SET monitoring_consent_version='monitoring-v2', monitoring_consented_at=now(), monitoring_enabled=true WHERE id='20000000-0000-0000-0000-000000000011';
INSERT INTO private.monitoring_sessions(id,channel_id,owner_id,provider_stream_id,title,started_at) VALUES ('30000000-0000-0000-0000-000000000011','20000000-0000-0000-0000-000000000011','00000000-0000-0000-0000-000000000011','stream-11','Live',now());
SELECT throws_ok($$INSERT INTO private.monitoring_sessions(channel_id,owner_id,provider_stream_id,title,started_at) VALUES ('20000000-0000-0000-0000-000000000011','00000000-0000-0000-0000-000000000011','stream-11','Again',now())$$,'23505',NULL,'stream cannot be duplicated');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000011',true);
SELECT throws_ok('SELECT * FROM private.monitoring_sessions','42501',NULL,'owner uses Sentry API for session metadata');
SELECT throws_ok('SELECT * FROM private.access_invites','42501',NULL,'browser cannot read invite hashes');
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000012',true);
SELECT throws_ok('SELECT * FROM private.monitoring_sessions','42501',NULL,'other member cannot read session directly');
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000013',true);
SELECT throws_ok('SELECT * FROM private.monitoring_sessions','42501',NULL,'admin uses Sentry API for session metadata');
RESET ROLE;
SELECT ok(has_table_privilege('vpn_sentry','private.monitoring_sessions','INSERT'),'Sentry may persist sessions');
SELECT ok(has_table_privilege('vpn_sentry','private.access_invites','INSERT'),'Sentry may persist private invites');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000011',true);
SELECT throws_ok($$INSERT INTO private.monitoring_sessions(channel_id,owner_id,provider_stream_id,title,started_at) VALUES ('20000000-0000-0000-0000-000000000011','00000000-0000-0000-0000-000000000011','stream-browser','Not allowed',now())$$,'42501',NULL,'browser cannot write session metadata');
RESET ROLE;
SET LOCAL ROLE anon;
SELECT throws_ok('SELECT * FROM private.monitoring_sessions','42501',NULL,'anonymous cannot read session metadata');
SELECT throws_ok('SELECT * FROM private.access_invites','42501',NULL,'anonymous cannot read invite metadata');
RESET ROLE;
SELECT * FROM finish();
ROLLBACK;
